-- Run time: 2026-11-10 21:58:48 HST
WITH mature_men_items AS ( SELECT CASE WHEN p.category = 'Accessories' THEN 'Men Accessories' ELSE 'Other Men categories' END AS comparison_group, oi.returned_at IS NOT NULL AS is_returned, oi.sale_price FROM `bigquery-public-data.thelook_ecommerce.order_items` AS oi JOIN `bigquery-public-data.thelook_ecommerce.products` AS p ON oi.product_id = p.id WHERE p.department = 'Men' AND oi.delivered_at IS NOT NULL AND DATE(oi.delivered_at) <= DATE_SUB(CURRENT_DATE(), INTERVAL 60 DAY) ) SELECT comparison_group, COUNT(*) AS mature_delivered_items, COUNTIF(is_returned) AS returned_items, ROUND(100 * SAFE_DIVIDE(COUNTIF(is_returned), COUNT(*)), 2) AS return_rate_pct, ROUND(SUM(IF(is_returned, sale_price, 0)), 2) AS returned_sale_price_total, ROUND(AVG(IF(is_returned, sale_price, NULL)), 2) AS average_returned_sale_price FROM mature_men_items GROUP BY comparison_group ORDER BY comparison_group;